{
  "title": "Detect Credential Stuffing via Failed Kerberos TGT Requests",
  "id": "e3b2c5d4-9f1a-4d2e-8c3f-1a2b3c4d5e6f",
  "description": "Multiple failed Kerberos TGT (Event ID 4768) requests from the same source IP within a short time window may indicate credential stuffing.",
  "status": "experimental",
  "author": "SOC Analyst",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4768,
      "LogonType": 2,
      "Status": "0x18"
    },
    "groupby": "src_ip",
    "condition": "selection | count() by src_ip >= 5 within 5 minutes"
  },
  "fields": ["src_ip", "target_user", "target_computer"],
  "falsepositives": ["Legitimate batch authentication"],
  "level": "high"
}

